  values ('ME', 'short_answer', 'Calculate the mole fraction of each component of a mixture made by dissolving 10.0 g of NaOH and 12.7 g of iodine in 54.0 g of water. (3 marks)', 'Moles of NaOH = 10.0 ÷ 40 = 0.25 mol; moles of I2 = 12.7 ÷ 254 = 0.05 mol; moles of H2O = 54.0 ÷ 18 = 3.00 mol. Total = 3.30 mol. Mole fraction of NaOH = 0.25 ÷ 3.30 = 0.076; of I2 = 0.05 ÷ 3.30 = 0.015; of H2O = 3.00 ÷ 3.30 = 0.909. (Check: 0.076 + 0.015 + 0.909 = 1.)', null, '[{"point": "Moles: NaOH = 10.0/40 = 0.25; I2 = 12.7/254 = 0.05; H2O = 54.0/18 = 3.00; total = 3.30", "marks": 1.5}, {"point": "Mole fractions: NaOH = 0.25/3.30 = 0.076; I2 = 0.05/3.30 = 0.015; H2O = 3.00/3.30 = 0.909 (sum = 1)", "marks": 1.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
