  values ('ME', 'short_answer', 'What are honey guides? What is their importance for the plant possessing them? (3 marks)', 'Honey guides (nectar guides) are coloured lines, spots or patterns on the petals of many flowers, often visible to insects in ultraviolet light, that point towards the nectar. They guide pollinating insects such as bees and butterflies straight to the nectar, and in doing so the insect brushes against the anthers and stigma. This makes pollination, especially cross-pollination, more efficient - pollinators spend less time searching, visit more flowers and carry pollen effectively - so the plant gets better seed and fruit set.', null, '[{"point": "Honey (nectar) guides: lines, spots or patterns on petals (often visible in UV to insects) leading to the nectar", "marks": 1}, {"point": "They direct pollinators (bees, butterflies) to the nectar and, on the way, past the anthers and stigma", "marks": 1}, {"point": "Importance: efficient pollination (cross-pollination), less wasted visits, more seed and fruit set", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
